// Decimator projection into the ordinary craps resolver. Settlement stays in the verified replay.
import { decimatorFieldPage } from '../app/decimator-battle-model.js';
const WEI = 10n ** 18n;
const LEGS = ['passLine', 'place4', 'place5', 'place6', 'place8', 'place9', 'place10', 'hard4', 'hard8', 'dontPassLine'];
export const decimatorWhole = value => BigInt(value ?? 0) / WEI;
export function decimatorEntryName(entry, names = new Map()) {
  return names.get(entry.address?.toLowerCase())?.name || (entry.address
    ? `${entry.address.slice(0, 6)}…${entry.address.slice(-4)}` : `Jackpot entry #${entry.entryId}`);
}
export function decimatorTableOptions(snapshot, replay, { names = new Map(), viewerEntryId, ...controls } = {}) {
  const owned = snapshot.battleEntries.filter(row => row.address?.toLowerCase() === snapshot.you?.address?.toLowerCase());
  const selected = snapshot.battleEntries.find(row => row.entryId === String(viewerEntryId))
    ?? owned.find(row => row.eligible) ?? owned[0] ?? replay.entries[0];
  if (!selected || !replay.frames.length) throw new Error('The Decimator dice are not available yet.');
  const viewer = replay.entries.find(row => row.entryId === selected.entryId);
  const frameCount = replay.frames.length;
  const resolutionHands = replay.frames.map((frame, index) => {
    const own = viewer?.resolutionFrames[index];
    return { ...own,
      dice: [frame.d1, frame.d2], shooter: frame.shooter, point: frame.point || null,
      label: own?.label ?? `${frame.label} · BATTLE CONTINUES`,
      bankrollFlip: own?.bankrollFlip ?? '0', deltaFlip: own?.deltaFlip ?? '0',
      returnedFlip: own?.returnedFlip ?? '0', boostFlip: own?.boostFlip ?? '0',
      viewerClosed: !own, viewerTerminal: own?.viewerTerminal ?? 'bust',
      terminal: index === frameCount - 1 ? 'bust' : '',
    };
  });
  const rows = replay.entries.map(entry => {
    const points = [entry.checkpoints[0], ...replay.frames.map(frame =>
      entry.checkpoints[Math.min(frame.completedHands, entry.handsPlayed)])];
    return { ...entry, label: decimatorEntryName(entry, names),
      avatar: names.get(entry.address?.toLowerCase())?.avatar ?? '',
      values: points.map(point => decimatorWhole(point.score)),
      rankValues: points.map(point => BigInt(point.rankScore)),
    };
  });
  // A killed viewer remains visible at zero and in the full field. It never receives invented dice.
  if (!viewer) rows.push({ ...selected, label: decimatorEntryName(selected, names),
    values: Array(frameCount + 1).fill(0n), rankValues: Array(frameCount + 1).fill(0n), totalRolls: 0 });
  return {
    ...controls, mode: 'slip', entryLabel: `DECIMATOR · LEVEL ${snapshot.level}`,
    tableResolved: true, showResolution: true, autoRoll: controls.autoRoll ?? false,
    playedFlip: '600', bankrollFlip: viewer ? '3000' : '0', goalFlip: '0',
    viewerBetId: selected.entryId, viewerPlayer: selected.address, viewerLabel: decimatorEntryName(selected, names),
    viewerDiscordPfp: names.get(selected.address?.toLowerCase())?.avatar,
    viewerResult: { stop: 'bust', exitRoll: viewer?.totalRolls ?? 0, handsPlayed: viewer?.handsPlayed ?? 0 },
    bets: Object.fromEntries(LEGS.map((leg, i) => [leg, viewer?.board[i] ?? 0])),
    fieldEntrants: snapshot.fieldEntries ?? snapshot.entrants,
    battleWinnerBetId: snapshot.championEntryId,
    battleWonByViewer: snapshot.winners.some(row => row.entryId === selected.entryId),
    resolutionHands,
    otherPlayers: replay.entries.filter(entry => entry !== viewer).map(entry => ({
      betId: entry.entryId, player: entry.address, label: decimatorEntryName(entry, names),
      discordPfp: names.get(entry.address?.toLowerCase())?.avatar,
      chips: Object.fromEntries(LEGS.map((leg, i) => [leg, entry.board[i]])),
      resolution: { type: 'bust', roll: entry.totalRolls, startingBankrollFlip: '3000', goalFlip: '0',
        bankrollsFlip: entry.resolutionFrames.map(frame => frame.bankrollFlip),
        rollEvents: entry.resolutionFrames,
        survivals: Array.from({ length: 48 }, (_, shooter) => entry.resolutionFrames.find(frame => frame.shooter === shooter && frame.survival)?.survival ?? null),
      },
    })),
    decimator: { snapshot, names, rows, selected, frameCount },
  };
}

export function decimatorTableStandings(skin, round, players) {
  const byId = new Map(players.map(player => [player.betId, player]));
  const complete = round >= skin.frameCount;
  return skin.rows.map(row => {
    const player = byId.get(row.entryId);
    const step = Math.min(round, row.values.length - 1);
    const ended = round >= row.totalRolls;
    return { ...player, betId: row.entryId, local: row.entryId === skin.selected.entryId,
      amount: row.values[step], highPoint: row.values[step], rankPeak: row.values[step],
      startingBankroll: decimatorWhole(row.stack), rankScore: row.rankValues[step], tieKey: BigInt(row.tieKey ?? 0),
      eligible: row.eligible, state: !row.eligible ? 'bust' : ended ? 'cashout' : 'live',
      status: !row.eligible ? 'DRAW OUT' : ended ? 'PEAK HELD' : 'LIVE',
      battleWinner: complete && skin.snapshot.championEntryId === row.entryId,
    };
  }).sort((a,b) => a.eligible !== b.eligible ? a.eligible ? -1 : 1
    : a.rankScore !== b.rankScore ? a.rankScore > b.rankScore ? -1 : 1
      : a.tieKey === b.tieKey ? 0 : a.tieKey > b.tieKey ? -1 : 1)
    .map((row, index) => ({ ...row, rank: row.eligible ? index + 1 : null }));
}

// Page the complete id space, including slots the chain never visited.
export function decimatorTableField(skin, offset = 0) {
  return decimatorFieldPage(skin.snapshot, { offset, limit: 25 });
}

/** The paid boundary so far, using only scores already revealed by this roll. */
export function decimatorCurrentCutoff(skin, round = 0) {
  const places = Number(skin.snapshot.winnerCount ?? skin.snapshot.winners.length);
  if (places <= 0) return null;
  const scores = skin.rows.filter(row => row.eligible).map(row =>
    row.values[Math.max(0, Math.min(round, row.values.length - 1))]);
  scores.sort((a, b) => a === b ? 0 : a > b ? -1 : 1);
  return scores[Math.min(places, scores.length) - 1] ?? null;
}

/** Peaks only rise. Clip at the crossing instead of flattening high scores onto the ceiling. */
export function decimatorVisiblePeakPoints(points, max) {
  const visible = [];
  for (const point of points) {
    if (point.value <= max) { visible.push(point); continue; }
    const previous = visible.at(-1);
    if (previous && previous.value < max) {
      const fraction = Number((max - previous.value) * 1_000_000n / (point.value - previous.value)) / 1_000_000;
      visible.push({ step: previous.step + (point.step - previous.step) * fraction, value: max });
    }
    break;
  }
  return visible;
}
